// 魂匠守衛者 — 音效模組 (window.Sound)
// 契約: init / play(name, opts) / playMusic(name) / stopMusic / setMuted(bool) / isMuted
// 事件表、呼叫時機與 opts 欄位見 sound.md。本檔由音效負責, RD 只需 <script src="audio/sound.js"> 並照 sound.md 呼叫。
// 音效: mp3 以 base64 內嵌(file:// 不能 fetch), 頁面載入時先離線解碼, init 後用 Web Audio 播放;
//       沒有 Web Audio 或解碼失敗時, 退回 audio/assets/ 下同名 mp3 的 HTMLAudio 播放池。
// 音樂: HTMLAudio 播 audio/assets/music_*.mp3, 兩個元素交叉淡化循環。
(function () {
  'use strict';
  var BASE = 'audio/assets/';
  // name -> { f: 檔名, p: 原音起音前的柔和前段秒數, b: base64 mp3 }
  var DATA = {
    "ui_move": {"f":"sfx_ui_move.mp3","p":0,"b":""},
    "ui_confirm": {"f":"sfx_ui_confirm.mp3","p":0.00007,"b":""},
    "ui_invalid": {"f":"sfx_ui_invalid.mp3","p":0.00002,"b":""},
    "popup_open": {"f":"sfx_popup_open.mp3","p":0.0205,"b":""},
    "popup_close": {"f":"sfx_popup_close.mp3","p":0.00014,"b":""},
    "take_part": {"f":"sfx_take_part.mp3","p":0.00367,"b":""},
    "install_part": {"f":"sfx_install_part.mp3","p":0.00005,"b":""},
    "swap_part": {"f":"sfx_swap_part.mp3","p":0.0046,"b":""},
    "drop_part": {"f":"sfx_drop_part.mp3","p":0.00408,"b":""},
    "slot_expand": {"f":"sfx_slot_expand.mp3","p":0.0024,"b":""},
    "purchase": {"f":"sfx_purchase.mp3","p":0.00889,"b":""},
    "place_unit": {"f":"sfx_place_unit.mp3","p":0.00009,"b":""},
    "coin_pickup": {"f":"sfx_coin_pickup.mp3","p":0.00574,"b":""},
    "steal_start": {"f":"sfx_steal_start.mp3","p":0.0078,"b":""},
    "steal_done": {"f":"sfx_steal_done.mp3","p":0.00347,"b":""},
    "steal_cancel": {"f":"sfx_steal_cancel.mp3","p":0.01231,"b":""},
    "combo": {"f":"sfx_combo.mp3","p":0.00249,"b":""},
    "combo_new": {"f":"sfx_combo_new.mp3","p":0.00002,"b":""},
    "arrow_shot": {"f":"sfx_arrow_shot.mp3","p":0.00723,"b":""},
    "pierce_shot": {"f":"sfx_pierce_shot.mp3","p":0.0056,"b":""},
    "melee_hit": {"f":"sfx_melee_hit.mp3","p":0.00671,"b":""},
    "whirl": {"f":"sfx_whirl.mp3","p":0.0088,"b":""},
    "charge_hit": {"f":"sfx_charge_hit.mp3","p":0.00014,"b":""},
    "enemy_shot": {"f":"sfx_enemy_shot.mp3","p":0.0066,"b":""},
    "enemy_die": {"f":"sfx_enemy_die.mp3","p":0.01306,"b":""},
    "unit_down": {"f":"sfx_unit_down.mp3","p":0.00327,"b":""},
    "unit_return": {"f":"sfx_unit_return.mp3","p":0.0024,"b":""},
    "recruit": {"f":"sfx_recruit.mp3","p":0.00018,"b":""},
    "wave_warning": {"f":"sfx_wave_warning.mp3","p":0.00002,"b":""},
    "wave_start": {"f":"sfx_wave_start.mp3","p":0.00011,"b":""},
    "castle_hit": {"f":"sfx_castle_hit.mp3","p":0.0044,"b":""},
    "tutorial_done": {"f":"sfx_tutorial_done.mp3","p":0.00238,"b":""},
    "level_win": {"f":"sfx_level_win.mp3","p":0.0034,"b":""},
    "level_lose": {"f":"sfx_level_lose.mp3","p":0.00254,"b":""},
    "star": {"f":"sfx_star.mp3","p":0.00202,"b":""}
  };
  var MUSIC = {
    title: { file: 'music_title.mp3', vol: 0.25 },
    battle: { file: 'music_battle.mp3', vol: 0.30 }
  };
  // 同名事件最短間隔(毫秒)與同時發聲上限; 未列者用預設
  var GAP_DEFAULT = 25, VOICES_DEFAULT = 4;
  var GAP = { arrow_shot: 100, enemy_shot: 60, melee_hit: 50, pierce_shot: 60, whirl: 60, coin_pickup: 40, enemy_die: 40, charge_hit: 50 };
  var VOICES = { arrow_shot: 3, enemy_shot: 3, coin_pickup: 4, enemy_die: 4, level_win: 1, level_lose: 1, wave_start: 1, wave_warning: 1 };
  var FALLBACK_SKIP = 0.042; // HTMLAudio 退回模式時跳過的開頭(20ms 靜音頭 + 編碼延遲, Node 量得 25ms)
  var STAR_RATES = [1, 1.122, 1.26];
  var DUCK_VOL = 0.5, DUCK_RATE = 0.85, XF = 1.2;

  var inited = false, muted = false;
  var ctx = null, master = null;
  var buffers = {}, offsets = {}, lastAt = {}, voices = {}, pools = {};

  function now() { return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now(); }
  function b64ToAb(b64) {
    var bin = atob(b64), n = bin.length, u = new Uint8Array(n);
    for (var i = 0; i < n; i++) u[i] = bin.charCodeAt(i);
    return u.buffer;
  }
  // 頁面載入時就離線解碼(不需使用者操作), 讓第一鍵就有聲音
  function predecode() {
    var OAC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!OAC) return;
    var off;
    try { off = new OAC(1, 1, 44100); } catch (e) { return; }
    Object.keys(DATA).forEach(function (name) {
      var d = DATA[name];
      var ok = function (buf) {
        buffers[name] = buf;
        // 找第一個 |樣本| > 0.02, 扣掉原音本來就有的柔和前段, 得到要跳過的解碼器填充
        var x = buf.getChannelData(0), first = 0;
        for (var i = 0; i < x.length; i++) { if (x[i] > 0.02 || x[i] < -0.02) { first = i; break; } }
        offsets[name] = Math.max(0, first / buf.sampleRate - (d.p || 0) - 0.003);
      };
      try {
        var p = off.decodeAudioData(b64ToAb(d.b), ok, function () {});
        if (p && p.catch) p.catch(function () {});
      } catch (e) { /* 退回 HTMLAudio */ }
    });
  }

  function fallbackPlay(name, rate, vol) {
    var d = DATA[name]; if (!d || typeof Audio === 'undefined') return;
    var pool = pools[name];
    if (!pool) { pool = pools[name] = { els: [], i: 0 }; for (var k = 0; k < 3; k++) { var a = new Audio(BASE + d.f); a.preload = 'auto'; pool.els.push(a); } }
    var el = pool.els[pool.i]; pool.i = (pool.i + 1) % pool.els.length;
    try {
      el.pause();
      el.currentTime = FALLBACK_SKIP;
      el.playbackRate = rate;
      el.volume = Math.max(0, Math.min(1, vol));
      var pr = el.play(); if (pr && pr.catch) pr.catch(function () {});
    } catch (e) {}
  }

  function play(name, opts) {
    if (!inited || muted || !DATA.hasOwnProperty(name)) return;
    opts = opts || {};
    var t = now(), gap = GAP.hasOwnProperty(name) ? GAP[name] : GAP_DEFAULT;
    if (lastAt[name] !== undefined && t - lastAt[name] < gap) return;
    lastAt[name] = t;
    var rate = 1;
    if (name === 'star') { var idx = opts.index | 0; rate = STAR_RATES[Math.max(0, Math.min(2, idx))]; }
    else if (name === 'coin_pickup') rate = 0.94 + Math.random() * 0.14;
    else if (name === 'enemy_die' || name === 'melee_hit' || name === 'arrow_shot') rate = 0.95 + Math.random() * 0.1;
    var vol = (typeof opts.volume === 'number') ? Math.max(0, Math.min(1, opts.volume)) : 1;
    // 音效附帶的音樂行為: 彈窗(慢動作)壓低 battle 音樂; 結算時停音樂
    if (name === 'popup_open') setDuck(true);
    else if (name === 'popup_close') setDuck(false);
    else if (name === 'level_win' || name === 'level_lose') stopMusic();
    var buf = buffers[name];
    if (ctx && master && buf) {
      try {
        var src = ctx.createBufferSource(); src.buffer = buf; src.playbackRate.value = rate;
        var g = ctx.createGain(); g.gain.value = vol;
        src.connect(g); g.connect(master);
        var list = voices[name] || (voices[name] = []);
        var cap = VOICES.hasOwnProperty(name) ? VOICES[name] : VOICES_DEFAULT;
        while (list.length >= cap) { var old = list.shift(); try { old.stop(); } catch (e) {} }
        list.push(src);
        src.onended = function () { var i = list.indexOf(src); if (i >= 0) list.splice(i, 1); };
        src.start(0, offsets[name] || 0);
        return;
      } catch (e) { /* 落到退回模式 */ }
    }
    fallbackPlay(name, rate, vol);
  }

  // ---------- 背景音樂 ----------
  var tracks = {}, curName = null, ducked = false, faders = [], tick = null;
  function track(name) {
    var m = MUSIC[name]; if (!m || typeof Audio === 'undefined') return null;
    if (!tracks[name]) {
      var mk = function () { var a = new Audio(BASE + m.file); a.preload = 'auto'; a.loop = false; a.volume = 0; a._lvl = 0; return a; };
      tracks[name] = { els: [mk(), mk()], cur: 0, xfading: false, vol: m.vol };
    }
    return tracks[name];
  }
  function applyVol(tr, el) {
    var v = tr.vol * el._lvl * (ducked && curName && tracks[curName] === tr ? DUCK_VOL : 1);
    try { el.volume = Math.max(0, Math.min(1, v)); el.muted = muted; } catch (e) {}
  }
  function fade(tr, el, to, sec, thenPause) {
    for (var i = faders.length - 1; i >= 0; i--) if (faders[i].el === el) faders.splice(i, 1);
    faders.push({ tr: tr, el: el, from: el._lvl, to: to, t0: now(), dur: Math.max(1, sec * 1000), pause: !!thenPause });
    ensureTick();
  }
  function setRate(el, r) {
    try { el.preservesPitch = false; el.mozPreservesPitch = false; el.webkitPreservesPitch = false; el.playbackRate = r; } catch (e) {}
  }
  function startEl(tr, el, lvl) {
    try { el.currentTime = 0; } catch (e) {}
    el._lvl = lvl; setRate(el, ducked ? DUCK_RATE : 1); applyVol(tr, el);
    try { var p = el.play(); if (p && p.catch) p.catch(function () {}); } catch (e) {}
  }
  function ensureTick() { if (!tick) tick = setInterval(onTick, 50); }
  function onTick() {
    var t = now();
    for (var i = faders.length - 1; i >= 0; i--) {
      var f = faders[i], k = Math.min(1, (t - f.t0) / f.dur);
      f.el._lvl = f.from + (f.to - f.from) * k; applyVol(f.tr, f.el);
      if (k >= 1) { faders.splice(i, 1); if (f.pause) { try { f.el.pause(); } catch (e) {} } }
    }
    // 循環: 快到結尾時另一個元素從頭淡入, 目前的淡出
    if (curName) {
      var tr = tracks[curName], el = tr.els[tr.cur];
      var d = el.duration;
      if (!tr.xfading && d && isFinite(d) && d > XF * 3 && el.currentTime >= d - XF) {
        tr.xfading = true;
        var nx = 1 - tr.cur, ne = tr.els[nx];
        startEl(tr, ne, 0); fade(tr, ne, 1, XF, false); fade(tr, el, 0, XF, true);
        tr.cur = nx;
        setTimeout(function () { tr.xfading = false; }, XF * 1000 + 100);
      } else if (el.ended && !tr.xfading) { startEl(tr, el, 1); }
    }
    if (!faders.length && !curName) { clearInterval(tick); tick = null; }
  }
  var wantMusic = null;
  function playMusic(name) {
    if (!MUSIC.hasOwnProperty(name)) return;
    wantMusic = name;
    if (!inited) return; // init 時才真的開始
    if (curName === name) return;
    stopMusic(true);
    ducked = false;
    var tr = track(name); if (!tr) return;
    curName = name; wantMusic = name; tr.xfading = false;
    var el = tr.els[tr.cur];
    startEl(tr, el, 0); fade(tr, el, 1, 0.4, false);
  }
  function stopMusic(keepWant) {
    if (!keepWant) wantMusic = null;
    if (!curName) return;
    var tr = tracks[curName];
    tr.els.forEach(function (el) { if (!el.paused) fade(tr, el, 0, 0.6, true); });
    curName = null; ducked = false;
  }
  function setDuck(on) {
    on = !!on; if (ducked === on) return;
    ducked = on;
    if (!curName) return;
    var tr = tracks[curName];
    tr.els.forEach(function (el) { setRate(el, on ? DUCK_RATE : 1); applyVol(tr, el); });
  }

  function init() {
    if (!inited) {
      inited = true;
      var AC = window.AudioContext || window.webkitAudioContext;
      if (AC) {
        try { ctx = new AC(); master = ctx.createGain(); master.gain.value = muted ? 0 : 1; master.connect(ctx.destination); } catch (e) { ctx = null; master = null; }
      }
      if (wantMusic) { var w = wantMusic; wantMusic = null; playMusic(w); }
    }
    if (ctx && ctx.state === 'suspended' && ctx.resume) { try { var p = ctx.resume(); if (p && p.catch) p.catch(function () {}); } catch (e) {} }
  }
  function setMuted(b) {
    muted = !!b;
    if (master) { try { master.gain.value = muted ? 0 : 1; } catch (e) {} }
    Object.keys(tracks).forEach(function (k) { var tr = tracks[k]; tr.els.forEach(function (el) { applyVol(tr, el); }); });
  }
  function isMuted() { return muted; }

  try { predecode(); } catch (e) {}
  window.Sound = {
    init: function () { try { init(); } catch (e) {} },
    play: function (name, opts) { try { play(name, opts); } catch (e) {} },
    playMusic: function (name) { try { playMusic(name); } catch (e) {} },
    stopMusic: function () { try { stopMusic(false); } catch (e) {} },
    setMuted: function (b) { try { setMuted(b); } catch (e) {} },
    isMuted: isMuted
  };
})();
